 const [entries,setEntries]=useState<Row>(current?.entries||{}),[dirty,setDirty]=useState(false),[saving,setSaving]=useState(false),[saveError,setSaveError]=useState(''),[pasteError,setPasteError]=useState(''),[receipt,setReceipt]=useState<Row|null>(null),[localState,setLocalState]=useState(''),[savedAt,setSavedAt]=useState('');
