 const [roster,setRoster]=useState<Row[]>([]),[rosterReady,setRosterReady]=useState(false),[rosterError,setRosterError]=useState('');
 useEffect(()=>{let cancelled=false;const account=offline.owner,key='roster:'+account+':'+assignment.id+':'+period.id;
  async function load(){setRosterError('');try{
   const cached=await get('drafts',key);
   if(!navigator.onLine){if(current&&current.status!=='Draft'){if(!cancelled){setRoster(current.roster||[]);setRosterReady(true)}return;}if(!cached)throw Error('Open this class and quarter online once to prepare its authorized roster for offline work.');if(!cancelled){setRoster(cached.roster);setRosterReady(true)}return;}
   const result=await db!.rpc('grade_roster',{assignment:assignment.id,period:period.id});if(result.error)throw Error(result.error.message);
   if(cancelled||offline.owner!==account)return;setRoster(result.data);setRosterReady(true);
   try{await put('drafts',{key,owner:account,roster:result.data})}catch{if(!cancelled)setRosterError('Roster loaded online, but this device could not cache it for offline use. Free browser storage and retry.');}
  }catch(e){if(!cancelled){setRosterReady(false);setRosterError(message(e));}}}
  void load();window.addEventListener('online',load);return()=>{cancelled=true;window.removeEventListener('online',load)};
 },[assignment.id,period.id,current?.status,current?.sync_version]);

 // Keep the version from before editing. A background refresh must not authorize an overwrite.
 useEffect(()=>{if(!dirty&&!savingRef.current){baseline.current=current;setEntries(current?.entries||{})}},[current?.sync_version,current?.id]);
 useEffect(()=>{unsavedGradeChanges=dirty||saving;return()=>{unsavedGradeChanges=false}},[dirty,saving]);
 useEffect(()=>{if(!dirty&&!saving)return;const leave=(e:BeforeUnloadEvent)=>{e.preventDefault();e.returnValue=''};window.addEventListener('beforeunload',leave);return()=>window.removeEventListener('beforeunload',leave)},[dirty,saving]);
 useEffect(()=>{let stopped=false;const account=offline.owner;async function update(){const rows=await all<offline.LocalRecord>('records');const row=rows.find(r=>r.owner===account&&r.table==='grade_submissions'&&r.data.assignment_id===assignment.id&&r.data.period_id===period.id);if(!stopped&&offline.owner===account)setLocalState(row?.sync_status||'');}const refresh=()=>{void update().catch(()=>{if(!stopped)setLocalState('unknown')})};refresh();offline.events.addEventListener('change',refresh);return()=>{stopped=true;offline.events.removeEventListener('change',refresh)}},[assignment.id,period.id]);
 const activeEntries=Object.fromEntries(roster.map((r:Row)=>[r.enrollment_id,entries[r.enrollment_id]??null]));
 const missing=roster.filter((r:Row)=>activeEntries[r.enrollment_id]===null).length;
 const invalid=roster.filter((r:Row)=>!validGrade(activeEntries[r.enrollment_id],policy));
 async function saveDraft(){
  if(savingRef.current)return;const version=editVersion.current;savingRef.current=true;setSaving(true);setSaveError('');
  try{if(!rosterReady||locked||closed)throw Error('This grade sheet is not editable.');if(invalid.length)throw Error('Correct the highlighted grades before saving.');
   const saved=await offline.saveGradeDraft(assignment,period,activeEntries,baseline.current);baseline.current=saved;if(editVersion.current===version)setDirty(false);setSavedAt(new Date().toLocaleTimeString());setLocalState('pending_sync');
  }catch(e){setSaveError(message(e))}finally{savingRef.current=false;setSaving(false)}
 }
 useEffect(()=>{if(!dirty||saving||saveError||invalid.length||locked||closed||!rosterReady)return;const timer=setTimeout(()=>void saveDraft(),1200);return()=>clearTimeout(timer)},[entries,dirty,saving,saveError,locked,closed,rosterReady]);
